/* Lot 110: the lengths of the body box scroller, percentages of html's height (generated by scripts/lot110_gen.py; expectations from scripts/lot110_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[6144];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><div id=b><p id=i>i</p><p id=r>r</p></div></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    TEST_ASSERT_EQUAL(8, g_d.nnodes);
    wf_site_set_time(0);
}

/* the style attribute of the element with this id (html, body: by tag) */
static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id) || (!g_d.node[i].id[0] && !strcmp(g_d.node[i].tag, id)))
            wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l110_blen_0(void) {
    prep("@keyframes k { to { color: #ffffff } } html { overflow: clip; height: 2000px } body { overflow: hidden; height: 50vh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 0);
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 2));
    TEST_ASSERT_EQUAL(2, wf_site_scroller_of(&g_d, 5));
    TEST_ASSERT_EQUAL_STRING("", style_of("body"));
    prep("@keyframes k { to { color: #ffffff } } html { overflow: clip; height: 30em } body { overflow: hidden; height: 75%; max-height: 12.5%; font-size: 10px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 0);
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 2));
    TEST_ASSERT_EQUAL(2, wf_site_scroller_of(&g_d, 5));
    TEST_ASSERT_EQUAL_STRING(" style=\"font-size:10px\"", style_of("body"));
    prep("@keyframes k { to { color: #ffffff } } html { overflow: clip; height: auto } body { overflow: hidden; height: calc(50% + 10px); min-height: 2000% } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 0);
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 2));
    TEST_ASSERT_EQUAL(2, wf_site_scroller_of(&g_d, 5));
    TEST_ASSERT_EQUAL_STRING("", style_of("body"));
    prep("@keyframes k { to { color: #ffffff } } html { overflow: visible; height: auto } body { overflow: auto; max-height: 2000% } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 0);
    TEST_ASSERT_EQUAL(0, wf_site_box_scroller(&g_d, 2));
    TEST_ASSERT_EQUAL(-1, wf_site_scroller_of(&g_d, 5));
    TEST_ASSERT_EQUAL_STRING("", style_of("body"));
    prep("@keyframes k { to { color: #ffffff } } html { overflow: clip; height: 100% } body { overflow: hidden; height: auto } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 0);
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 2));
    TEST_ASSERT_EQUAL(2, wf_site_scroller_of(&g_d, 5));
    TEST_ASSERT_EQUAL_STRING("", style_of("body"));
    prep("@keyframes k { to { color: #ffffff } } html { overflow: hidden visible; height: 400px } body { overflow: hidden; height: 150%; max-height: 2000%; min-height: calc(50% + 10px) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 0);
    TEST_ASSERT_EQUAL(2, wf_site_box_scroller(&g_d, 2));
    TEST_ASSERT_EQUAL(2, wf_site_scroller_of(&g_d, 5));
    TEST_ASSERT_EQUAL_STRING("", style_of("body"));
    prep("@keyframes k { to { color: #ffffff } } html { overflow: clip; height: min-content } body { overflow: scroll; height: min(50%, 100px); max-height: 33.3% } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 0);
    TEST_ASSERT_EQUAL(5, wf_site_box_scroller(&g_d, 2));
    TEST_ASSERT_EQUAL(2, wf_site_scroller_of(&g_d, 5));
    TEST_ASSERT_EQUAL_STRING(" style=\"overflow-y:scroll;height:min(50%, 100px);max-height:33%\"", style_of("body"));
    prep("@keyframes k { to { color: #ffffff } } html { overflow: hidden; height: 10% } body { overflow: scroll; height: calc(50% + 10px); max-height: 50% } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 0);
    TEST_ASSERT_EQUAL(5, wf_site_box_scroller(&g_d, 2));
    TEST_ASSERT_EQUAL(2, wf_site_scroller_of(&g_d, 5));
    TEST_ASSERT_EQUAL_STRING(" style=\"overflow-y:scroll;height:calc(50% + 10px);max-height:24px\"", style_of("body"));
}

